mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("words=[crab,crate,rust] prefix=cr","2"),
        ("words=[cat,dog] prefix=ca","1"),
        ("words=[aa,ab,ba] prefix=a","2"),
        ("words=[rust,run] prefix=z","0"),
        ("words=[abc,abcd,abc] prefix=abc","3"),
        ("  \nwords=[crab,crate,rust] prefix=cr\n  ","2"),
        ("\nwords=[abc,abcd,abc] prefix=abc\n","3")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS trie");
}
